import gleam/list
import gleam/int
import gleam/io
import core/matrix.{type Matrix, from_list, rows, cols, ones, concatenate_columns, take_columns, stack_rows, get_row}

pub fn batch_sequences(sequences: List(List(Int)), max_len: Int) -> List(Matrix) {
    list.map(sequences, fn(seq) {
        let padded = case list.length(seq) < max_len {
            True -> list.append(seq, list.repeat(0, max_len - list.length(seq)))
            False -> list.take(seq, max_len)
        }
        from_list([padded |> list.map(int.to_float)])
    })
}

pub fn pad_batch(batch: List(Matrix)) -> Matrix {
    let row_list = list.map(batch, rows)
    let col_list = list.map(batch, cols)
    let max_rows = list.fold(row_list, 0, fn(a, b) { case a > b {
        True -> a
        False -> b
    } })
    let max_cols = list.fold(col_list, 0, fn(a, b) { case a > b {
        True -> a
        False -> b
    } })
    let padded_batch = list.map(batch, fn(mat) {
        let current_rows = rows(mat)
        let current_cols = cols(mat)
        let padded_mat = case current_cols < max_cols {
            True -> concatenate_columns(mat, ones(current_rows, max_cols - current_cols))
            False -> take_columns(mat, max_cols)
        }
        case current_rows < max_rows {
            True -> stack_rows([padded_mat, ones(max_rows - current_rows, max_cols)])
            False -> padded_mat
        }
    })
    stack_rows(padded_batch)
}

pub fn unbatch(batch: Matrix, batch_size: Int) -> List(Matrix) {
    let row_len = rows(batch) / batch_size
    list.map(list.range(0, batch_size - 1), fn(i) {
        from_list([get_row(batch, i * row_len)])
    })
}

pub fn main() {
    let sequences = list.map(list.range(0, 10), fn(i) { list.range(0, i) })
    let _batched = batch_sequences(sequences, 5)
    io.println("Batched sequences")
    Nil
}
