import gleam/list
import gleam/result
import gleam/option.{type Option, None, Some}
import gleam/float

pub type Category(obj, morph) {
  Category(
    objects: List(obj),
    morphisms: List(Morphism(obj, morph)),
    composition: fn(Morphism(obj, morph), Morphism(obj, morph)) -> Result(Morphism(obj, morph), String),
    identity: fn(obj) -> Morphism(obj, morph),
  )
}

pub type Morphism(obj, morph) {
  Morphism(
    source: obj,
    target: obj,
    transformation: morph,
  )
}

pub type Functor(c1_obj, c1_morph, c2_obj, c2_morph) {
  Functor(
    object_map: fn(c1_obj) -> c2_obj,
    morphism_map: fn(Morphism(c1_obj, c1_morph)) -> Morphism(c2_obj, c2_morph),
  )
}

pub type NaturalTransformation(c1_obj, c1_morph, c2_obj, c2_morph) {
  NaturalTransformation(
    source_functor: Functor(c1_obj, c1_morph, c2_obj, c2_morph),
    target_functor: Functor(c1_obj, c1_morph, c2_obj, c2_morph),
    components: fn(c1_obj) -> Morphism(c2_obj, c2_morph),
  )
}

pub type KANLayer {
  KANLayer(
    input_dim: Int,
    output_dim: Int,
    coefficients: List(List(Float)),
  )
}

pub fn kan_category() -> Category(Int, KANLayer) {
  Category(
    objects: list.range(1, 1000),
    morphisms: [],
    composition: compose_kan_morphisms,
    identity: identity_kan_morphism,
  )
}

fn compose_kan_morphisms(
  f: Morphism(Int, KANLayer),
  g: Morphism(Int, KANLayer),
) -> Result(Morphism(Int, KANLayer), String) {
  case f.target == g.source {
    False -> Error("Morphisms not composable: target/source mismatch")
    True -> {
      let composed_coeffs = matrix_multiply(
        g.transformation.coefficients,
        f.transformation.coefficients,
      )

      Ok(Morphism(
        source: f.source,
        target: g.target,
        transformation: KANLayer(
          input_dim: f.transformation.input_dim,
          output_dim: g.transformation.output_dim,
          coefficients: composed_coeffs,
        ),
      ))
    }
  }
}

fn identity_kan_morphism(dim: Int) -> Morphism(Int, KANLayer) {
  let identity_matrix = list.range(0, dim - 1)
    |> list.map(fn(i) {
      list.range(0, dim - 1)
      |> list.map(fn(j) {
        case i == j {
          True -> 1.0
          False -> 0.0
        }
      })
    })

  Morphism(
    source: dim,
    target: dim,
    transformation: KANLayer(
      input_dim: dim,
      output_dim: dim,
      coefficients: identity_matrix,
    ),
  )
}

fn matrix_multiply(a: List(List(Float)), b: List(List(Float))) -> List(List(Float)) {
  let b_t = transpose(b)

  list.map(a, fn(row) {
    list.map(b_t, fn(col) {
      list.zip(row, col)
      |> list.map(fn(pair) { pair.0 *. pair.1 })
      |> list.fold(0.0, float.add)
    })
  })
}

fn transpose(matrix: List(List(Float))) -> List(List(Float)) {
  case matrix {
    [] -> []
    [first, ..] -> {
      let cols = list.length(first)
      list.range(0, cols - 1)
      |> list.map(fn(i) {
        list.filter_map(matrix, fn(row) {
          list.at(row, i)
        })
      })
    }
  }
}

pub fn kan_endofunctor() -> Functor(Int, KANLayer, Int, KANLayer) {
  Functor(
    object_map: fn(n) { n * 2 },
    morphism_map: fn(morph) {
      Morphism(
        source: morph.source * 2,
        target: morph.target * 2,
        transformation: KANLayer(
          input_dim: morph.transformation.input_dim * 2,
          output_dim: morph.transformation.output_dim * 2,
          coefficients: expand_coefficients(morph.transformation.coefficients),
        ),
      )
    },
  )
}

fn expand_coefficients(coeffs: List(List(Float))) -> List(List(Float)) {
  list.flat_map(coeffs, fn(row) {
    [list.flat_map(row, fn(x) { [x, x] }), list.flat_map(row, fn(x) { [x, x] })]
  })
}
