import gleam/float
import gleam/int
import gleam/list
import gleam/result
import core/matrix.{type Matrix}

pub type FractalPattern {
  Mandelbrot
  Julia
  Sierpinski
  KochSnowflake
  Custom(iterations: Int, self_similarity: Float)
}

pub type FractalKANLayer {
  FractalKANLayer(
    input_dim: Int,
    output_dim: Int,
    fractal_depth: Int,
    pattern: FractalPattern,
    self_similarity_factor: Float,
    sub_layers: List(FractalKANLayer),
    weights: Matrix,
    control_points: Matrix,
  )
}

pub fn create_fractal_layer(
  input_dim: Int,
  output_dim: Int,
  depth: Int,
  pattern: FractalPattern,
) -> FractalKANLayer {
  let self_sim = case pattern {
    Mandelbrot -> 0.618
    Julia -> 0.577
    Sierpinski -> 0.5
    KochSnowflake -> 0.333
    Custom(_, s) -> s
  }

  let sub_layers = case depth > 0 {
    True -> list.map(list.range(0, 2), fn(_) {
      create_fractal_layer(
        input_dim / 2,
        output_dim / 2,
        depth - 1,
        pattern,
      )
    })
    False -> []
  }

  FractalKANLayer(
    input_dim: input_dim,
    output_dim: output_dim,
    fractal_depth: depth,
    pattern: pattern,
    self_similarity_factor: self_sim,
    sub_layers: sub_layers,
    weights: matrix.random(output_dim, input_dim),
    control_points: matrix.random(output_dim, 10),
  )
}

pub fn fractal_forward(layer: FractalKANLayer, input: Matrix) -> Matrix {
  let base_output = matrix.multiply(layer.weights, input)

  case list.length(layer.sub_layers) {
    0 -> base_output
    _ -> {
      let split_inputs = split_matrix_fractal(input, list.length(layer.sub_layers))

      let sub_outputs = list.map2(layer.sub_layers, split_inputs, fn(sub_layer, sub_input) {
        let scaled = matrix.scale(sub_input, layer.self_similarity_factor)
        fractal_forward(sub_layer, scaled)
      })

      let combined = combine_fractal_outputs(sub_outputs)
      matrix.add(base_output, matrix.scale(combined, layer.self_similarity_factor))
    }
  }
}

fn split_matrix_fractal(m: Matrix, parts: Int) -> List(Matrix) {
  let rows_per_part = matrix.rows(m) / parts
  list.map(list.range(0, parts - 1), fn(i) {
    let start_row = i * rows_per_part
    let end_row = int.min((i + 1) * rows_per_part, matrix.rows(m))
    matrix.slice_rows(m, start_row, end_row)
  })
}

fn combine_fractal_outputs(outputs: List(Matrix)) -> Matrix {
  case outputs {
    [] -> matrix.zeros(1, 1)
    [single] -> single
    _ -> list.fold(list.drop(outputs, 1), result.unwrap(list.first(outputs), matrix.zeros(1, 1)), matrix.add)
  }
}
