import gleam/list
import gleam/float
import gleam/int
import gleam/result
import gleam/dict.{type Dict}

pub type Multivector {
  Multivector(
    scalar: Float,
    vectors: List(Float),
    bivectors: List(Float),
    trivectors: List(Float),
    pseudoscalar: Float,
  )
}

pub type CliffordAlgebra {
  CliffordAlgebra(
    dimension: Int,
    metric: List(Float),
    basis_elements: Dict(String, Multivector),
  )
}

pub fn create_clifford_algebra(dim: Int, metric: List(Float)) -> CliffordAlgebra {
  CliffordAlgebra(
    dimension: dim,
    metric: metric,
    basis_elements: generate_basis(dim),
  )
}

fn generate_basis(dim: Int) -> Dict(String, Multivector) {
  dict.new()
  |> dict.insert("scalar", Multivector(
    scalar: 1.0,
    vectors: list.repeat(0.0, dim),
    bivectors: list.repeat(0.0, dim * {dim - 1} / 2),
    trivectors: [],
    pseudoscalar: 0.0,
  ))
}

pub fn geometric_product(a: Multivector, b: Multivector) -> Multivector {
  let scalar = a.scalar *. b.scalar -. 
    list.zip(a.vectors, b.vectors)
    |> list.map(fn(p) { p.0 *. p.1 })
    |> list.fold(0.0, float.add)

  let vectors = list.index_map(a.vectors, fn(av, i) {
    let bv = result.unwrap(list.at(b.vectors, i), 0.0)
    a.scalar *. bv +. b.scalar *. av
  })

  let bivectors = compute_bivector_product(a, b)

  Multivector(
    scalar: scalar,
    vectors: vectors,
    bivectors: bivectors,
    trivectors: [],
    pseudoscalar: 0.0,
  )
}

fn compute_bivector_product(a: Multivector, b: Multivector) -> List(Float) {
  let n = list.length(a.vectors)

  list.flat_map(list.range(0, n - 1), fn(i) {
    list.filter_map(list.range(i + 1, n - 1), fn(j) {
      let ai = result.unwrap(list.at(a.vectors, i), 0.0)
      let aj = result.unwrap(list.at(a.vectors, j), 0.0)
      let bi = result.unwrap(list.at(b.vectors, i), 0.0)
      let bj = result.unwrap(list.at(b.vectors, j), 0.0)

      Ok(ai *. bj -. aj *. bi)
    })
  })
}

pub fn outer_product(a: Multivector, b: Multivector) -> Multivector {
  Multivector(
    scalar: 0.0,
    vectors: list.map2(a.vectors, b.vectors, fn(av, bv) { av *. b.scalar +. a.scalar *. bv }),
    bivectors: compute_bivector_product(a, b),
    trivectors: [],
    pseudoscalar: 0.0,
  )
}

pub fn inner_product(a: Multivector, b: Multivector) -> Float {
  a.scalar *. b.scalar +.
  list.zip(a.vectors, b.vectors)
  |> list.map(fn(p) { p.0 *. p.1 })
  |> list.fold(0.0, float.add)
}

pub fn embed_token_as_multivector(
  token_id: Int,
  vocab_size: Int,
  dim: Int,
) -> Multivector {
  let phase = 2.0 *. 3.14159265359 *. int.to_float(token_id) /. int.to_float(vocab_size)

  Multivector(
    scalar: result.unwrap(float.cos(phase), 0.0),
    vectors: list.range(0, dim - 1) 
      |> list.map(fn(i) { 
        result.unwrap(float.sin(phase *. int.to_float(i + 1)), 0.0)
      }),
    bivectors: [],
    trivectors: [],
    pseudoscalar: 0.0,
  )
}

pub fn rotor_rotation(mv: Multivector, angle: Float, plane_bivector: List(Float)) -> Multivector {
  let half_angle = angle /. 2.0
  let cos_half = result.unwrap(float.cos(half_angle), 1.0)
  let sin_half = result.unwrap(float.sin(half_angle), 0.0)

  let rotor = Multivector(
    scalar: cos_half,
    vectors: [],
    bivectors: list.map(plane_bivector, fn(b) { b *. sin_half }),
    trivectors: [],
    pseudoscalar: 0.0,
  )

  let rotor_inv = Multivector(
    scalar: cos_half,
    vectors: [],
    bivectors: list.map(plane_bivector, fn(b) { b *. -1.0 *. sin_half }),
    trivectors: [],
    pseudoscalar: 0.0,
  )

  geometric_product(geometric_product(rotor, mv), rotor_inv)
}
