import gleam/list
import gleam/float
import gleam/result

pub type HyperNetworkKAN {
  HyperNetworkKAN(
    meta_network_weights: List(List(List(Float))),
    target_kan_shape: KANShape,
    embedding_dim: Int,
  )
}

pub type KANShape {
  KANShape(
    input_dim: Int,
    output_dim: Int,
    grid_size: Int,
    degree: Int,
  )
}

pub fn create(
  embedding_dim: Int,
  target_shape: KANShape,
  meta_layers: List(Int),
) -> HyperNetworkKAN {
  let total_params = target_shape.input_dim * target_shape.output_dim * 
    {target_shape.grid_size + target_shape.degree}

  let weights = initialize_meta_network(embedding_dim, meta_layers, total_params)

  HyperNetworkKAN(
    meta_network_weights: weights,
    target_kan_shape: target_shape,
    embedding_dim: embedding_dim,
  )
}

fn initialize_meta_network(
  input_dim: Int,
  hidden_dims: List(Int),
  output_dim: Int,
) -> List(List(List(Float))) {
  let dims = [input_dim, ..hidden_dims] |> list.append([output_dim])

  list.window_by_2(dims)
  |> list.map(fn(pair) {
    let in_d = pair.0
    let out_d = pair.1
    list.repeat(list.repeat(0.01, out_d), in_d)
  })
}

pub fn generate_kan_weights(
  hyper: HyperNetworkKAN,
  context_embedding: List(Float),
) -> List(List(Float)) {
  let activations = forward_meta_network(
    hyper.meta_network_weights,
    context_embedding,
  )

  let total_params = hyper.target_kan_shape.input_dim * 
    hyper.target_kan_shape.output_dim * 
    {hyper.target_kan_shape.grid_size + hyper.target_kan_shape.degree}

  chunk_weights(activations, hyper.target_kan_shape)
}

fn forward_meta_network(
  weights: List(List(List(Float))),
  input: List(Float),
) -> List(Float) {
  list.fold(weights, input, fn(activation, layer_weights) {
    list.map(layer_weights, fn(neuron_weights) {
      let weighted_sum = list.zip(activation, neuron_weights)
        |> list.map(fn(pair) { pair.0 *. pair.1 })
        |> list.fold(0.0, float.add)

      tanh(weighted_sum)
    })
  })
}

fn tanh(x: Float) -> Float {
  let exp_2x = result.unwrap(float.power(2.718281828, 2.0 *. x), 1.0)
  {exp_2x -. 1.0} /. {exp_2x +. 1.0}
}

fn chunk_weights(flat_weights: List(Float), shape: KANShape) -> List(List(Float)) {
  let chunk_size = shape.grid_size + shape.degree

  list.sized_chunk(flat_weights, chunk_size)
  |> list.sized_chunk(shape.output_dim)
}

pub fn adaptive_forward(
  hyper: HyperNetworkKAN,
  input: List(Float),
  context: List(Float),
) -> List(Float) {
  let kan_weights = generate_kan_weights(hyper, context)

  list.map(kan_weights, fn(output_weights) {
    list.zip(input, output_weights)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)
  })
}
